import{_ as i,C as t,o as s,c as r,E as a,a2 as d}from"./chunks/framework.Cm6XCzck.js";const f=JSON.parse('{"title":"You Approved One Command. Why Did Another Pass? An Experiment in Agent Authorization Identity","description":"","frontmatter":{"schema":"publication-candidate-article/v2","title":"You Approved One Command. Why Did Another Pass? An Experiment in Agent Authorization Identity","date":"2026-09-04","published_date":"2026-09-04","column":"open-source-engineering","category":"daily","article_type":"experiment-report","edition":"research-center","research_question":"Does the real tool entry preserve approval-relevant operation distinctions while separating session context from operation identity?","summary":"In the same Agent approval pipeline, changing a Git branch left the authorization digest unchanged, while changing only the Session changed it. Real services, cross-process records, and negative controls show why risk classification, operation identity, and execution authority need different tests.","cover":"/assets/approval-identity-20260904/assets/approval-identity-cover-v2.png","language":"en","lifecycle":"Published","publication_authorized":true,"evidence_status":"Controlled experiments on a fixed baseline; no fix or independent QA claimed","sources":["https://github.com/openai/codex/pull/42588","https://github.com/openai/codex/pull/42579"]},"headers":[],"relativePath":"en/engineering/2026-09-04-approval-operation-identity.md","filePath":"en/engineering/2026-09-04-approval-operation-identity.md","lastUpdated":1788532182000}'),p={name:"en/engineering/2026-09-04-approval-operation-identity.md"};function c(l,e,h,u,m,g){const n=t("ArticleCover"),o=t("ArticleTableScroll");return s(),r("div",null,[a(n,{image:"/assets/approval-identity-20260904/assets/approval-identity-cover-v2.png",kicker:"Open-source engineering · Controlled experiment",title:"You Approved One Command. Why Did Another Pass? An Experiment in Agent Authorization Identity",summary:"In the same Agent approval pipeline, changing a Git branch left the authorization digest unchanged, while changing only the Session changed it. Real services, cross-process records, and negative controls show why risk classification, operation identity, and execution authority need different tests.",version:"2026-09-04",languageHref:"/zh/engineering/2026-09-04-approval-operation-identity",languageLabel:"中文"}),a(o,{language:"en"}),e[0]||(e[0]=d(`<h1 id="you-approved-one-command-why-did-another-pass-an-experiment-in-agent-authorization-identity" tabindex="-1">You Approved One Command. Why Did Another Pass? An Experiment in Agent Authorization Identity <a class="header-anchor" href="#you-approved-one-command-why-did-another-pass-an-experiment-in-agent-authorization-identity" aria-label="Permalink to &quot;You Approved One Command. Why Did Another Pass? An Experiment in Agent Authorization Identity&quot;">​</a></h1><p>We first created an approval for this command:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git push origin codex/research-probe</span></span></code></pre></div><p>Then we kept the project, task, agent, and session unchanged, but changed the target branch:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>git push origin codex/another-target</span></span></code></pre></div><p>The second command passed the approval decision. The first command&#39;s authorization was marked as consumed.</p><p>Another experiment produced the opposite surprise. We left the command unchanged and replaced only the session with the wake session registered in the approval record. The system requested approval again.</p><p><strong>An operation change that should have mattered did not. A session transition the system intended to support changed the match instead.</strong></p><p>This was an isolated, controlled experiment, not a production push incident. Neither command actually ran. The decision code and approval persistence, however, were real product implementations.</p><h2 id="_1-why-investigate-this-boundary" tabindex="-1">1. Why investigate this boundary? <a class="header-anchor" href="#_1-why-investigate-this-boundary" aria-label="Permalink to &quot;1. Why investigate this boundary?&quot;">​</a></h2><p>CodeFlowMu is a local multi-Agent collaboration system we are developing. Its FCoP file protocol preserves formal tasks and collaboration records, so a task&#39;s identity does not depend on one Agent session remaining alive. The runtime must answer a separate question: when an Agent requests an operation that requires approval, what exactly does that approval cover?</p><p>Recovery makes the question difficult. An original session may stop and another may take over. The approval record and task files remain. Their existence cannot automatically authorize execution, but irrelevant context changes should not accidentally destroy a recognizable operation identity either.</p><p>Recent Codex changes prompted this investigation. Codex is OpenAI&#39;s coding agent; Guardian is part of its tool-safety review machinery. <a href="https://github.com/openai/codex/pull/42588" target="_blank" rel="noreferrer">PR #42588</a>, merged on September 3, checks the producer compatibility of compaction checkpoints in a specific context mode. Missing or incompatible provenance requires synchronous review rather than allowing a fast decision that omits the checkpoint. <a href="https://github.com/openai/codex/pull/42579" target="_blank" rel="noreferrer">PR #42579</a> retains host-verified user answers and restricts fast approval when the evidence is incomplete.</p><p>Those changes concern <strong>whether evidence is usable for a current Codex review</strong>. They do not establish the Git digest defect in this article, nor suggest that CodeFlowMu should build another Guardian. We extracted a narrower question:</p><p><strong>Why does this existing approval apply to this particular call?</strong></p><p>An <code>approved</code> field alone cannot answer it.</p><h2 id="_2-approval-protections-already-existed" tabindex="-1">2. Approval protections already existed <a class="header-anchor" href="#_2-approval-protections-already-existed" aria-label="Permalink to &quot;2. Approval protections already existed&quot;">​</a></h2><p>We fixed the source at <code>fdadbed489129455437f25202a03bae6e0c2e822</code>, the V2.2.8-related baseline used in this study. Subsequent changes to main do not change this experiment&#39;s claims.</p><p>First, we reran four existing suites covering operation approvals, parent/child task identity, evidence association, and credential redaction. Both runs produced <strong>31 passes, no failures, and no skips</strong>. That means 31 tests repeated twice—not 62 independent scenarios, and not full-product acceptance.</p><p>The approval tests already demonstrated useful protections: a changed request target is rejected, an approval is consumed once, some recovery calls can read existing records, and manually constructed requests support Session continuation.</p><p>We therefore did not conclude that the system lacked approval or needed idempotency added from scratch. The next question was whether <strong>requests constructed by the actual tool entry point preserve the identity information those tests assume</strong>.</p><p>Our probe passed through the real Native approval gate, created a pending record, and approved it through the service. A separate Node process then read that record and requested consumption. Calls that passed were retried from another process. This ruled out an explanation based solely on in-memory approval state; it was not a power-loss test.</p><p>Eleven inputs were tested twice, with consistent outcomes:</p><table tabindex="0"><thead><tr><th>Change relative to the approved request</th><th>Actual gate result</th><th>Authorization record</th></tr></thead><tbody><tr><td>Same session and operation</td><td>Allowed; replay reported already consumed</td><td>consumed</td></tr><tr><td>Only use the registered wake session</td><td>Approval required again</td><td>available</td></tr><tr><td>Use another nonempty session</td><td>Approval required again</td><td>available</td></tr><tr><td>Omit the session</td><td>Approval required again</td><td>available</td></tr><tr><td>Change Agent</td><td>Approval required again</td><td>available</td></tr><tr><td>Change TASK</td><td>Approval required again</td><td>available</td></tr><tr><td>Change thread</td><td>Approval required again</td><td>available</td></tr><tr><td>Change project</td><td>Approval required again</td><td>available</td></tr><tr><td>Same session, change only the push branch</td><td><strong>Allowed; replay reported already consumed</strong></td><td><strong>consumed</strong></td></tr><tr><td>Change the source channel</td><td>Approval required again</td><td>available</td></tr><tr><td>Cancel while pending, without approval</td><td>Approval required again</td><td>invalid</td></tr></tbody></table><p>Whether different source channels should be equivalent needs its own contract; we do not classify that row as a defect. The session rows also do not prove that a real successor had satisfied every takeover requirement. The experiment changed the session input and registered a corresponding wake session.</p><p>The two opposing results warranted investigation: a branch change was accepted, while a session-only change failed to match. The complete probe retained both expectation violations, twice each, and exited with an assertion failure. We did not turn it into an all-green report. The <a href="/joinwell52/en/research/evidence/2026-09-04-approval-operation-identity">companion evidence guide</a> maps the individual observations.</p><h2 id="_3-the-hash-did-not-collide-the-operation-information-disappeared-first" tabindex="-1">3. The hash did not collide. The operation information disappeared first <a class="header-anchor" href="#_3-the-hash-did-not-collide-the-operation-information-disappeared-first" aria-label="Permalink to &quot;3. The hash did not collide. The operation information disappeared first&quot;">​</a></h2><p>The approval pipeline has several distinct responsibilities:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Tool name and arguments</span></span>
<span class="line"><span>→ Adapter extracts operation facts</span></span>
<span class="line"><span>→ Construct operation fingerprint and approval request</span></span>
<span class="line"><span>→ Compute request digest</span></span>
<span class="line"><span>→ Match an approved record</span></span>
<span class="line"><span>→ Consume once</span></span></code></pre></div><p>The operation fingerprint identifies the extracted facts. The request digest binds the approval request. Neither is inherently a substitute for the original command.</p><p>In the tested implementation, the shell adapter recognizes <code>git push</code> as a remote Git write, so the initial call requires approval. That risk classification works.</p><p>But it does not preserve the remote, branch references, or force/delete distinctions in these commands as corresponding operation identity information. The probe&#39;s target arrays are empty while completeness remains true. The approval request does not restore those distinctions from the original command.</p><p>“Both are remote Git writes” consequently becomes “both are the same approved operation.”</p><p><a href="https://joinwell52-ai.github.io/joinwell52/assets/approval-identity-20260904/assets/operation-collapse.en.png" target="_blank" rel="noreferrer"><img src="https://joinwell52-ai.github.io/joinwell52/assets/approval-identity-20260904/assets/operation-collapse.en.png" alt="Figure 1: Different branch commands produce the same approval identity"></a></p><p><em>Figure 1. Command distinctions disappear before hashing. Source: fixed-baseline field comparisons, approval gate and local Codex resolution observations; no actual push was performed. Click the image for full resolution.</em></p><p>We compared seven inputs field by field, twice each:</p><table tabindex="0"><thead><tr><th>Change</th><th>Operation fingerprint</th><th>Request digest</th></tr></thead><tbody><tr><td>Identical request</td><td>Same</td><td>Same</td></tr><tr><td>Different branch</td><td>Same</td><td>Same</td></tr><tr><td>Different remote</td><td>Same</td><td>Same</td></tr><tr><td>Add <code>--force</code></td><td>Same</td><td>Same</td></tr><tr><td>Change to <code>--delete</code></td><td>Same</td><td>Same</td></tr><tr><td>Different Session only</td><td>Same</td><td><strong>Different</strong></td></tr><tr><td>Different TASK</td><td>Different</td><td>Different</td></tr></tbody></table><p>This is not a cryptographic collision in SHA-256. After adaptation, the four operation-changing variants produce approval requests with no field differences. <strong>Different inputs were reduced to the same object before hashing. The hash faithfully produced the same value for that same object.</strong></p><p>The TASK negative control matters: the function is not returning a constant for everything. Specific semantic distinctions are missing from its input.</p><p>We also called the actual local resolution function for Codex native approval requests. The original command and the changed-branch command were each tested twice. All four decisions allowed the call and consumed the approval. That reaches the product&#39;s Codex approval-resolution entry point, but we did not start a Codex app-server, send a real approval response, or execute a push.</p><p>The distinction is important: <strong>remote, force, and delete changes were verified at the digest-equality boundary; the branch change was additionally verified at approval consumption.</strong> These are not reports of those operations executing.</p><p>This also explains why single consumption cannot protect the boundary by itself. It answers “Has this approval been used?” rather than “Is the operation using it the one that was approved?”</p><h2 id="_4-session-was-excluded-at-the-top-level—and-returned-through-the-snapshot" tabindex="-1">4. Session was excluded at the top level—and returned through the snapshot <a class="header-anchor" href="#_4-session-was-excluded-at-the-top-level—and-returned-through-the-snapshot" aria-label="Permalink to &quot;4. Session was excluded at the top level—and returned through the snapshot&quot;">​</a></h2><p>The opposite anomaly came from another field.</p><p>The lower-level <code>computeOperationDigest</code> explicitly excludes <code>subject.session_id</code> at the top of the request. This is consistent with the existing continuation test: an otherwise matching operation need not always complete in its original session.</p><p>The real request builder also embeds the complete operation facts in a snapshot. Changing only the Session produces two differences:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>subject.session_id</span></span>
<span class="line"><span>snapshot.operation_facts.subject.session_id</span></span></code></pre></div><p>The digest function excludes the first, but not the second.</p><p><a href="https://joinwell52-ai.github.io/joinwell52/assets/approval-identity-20260904/assets/nested-session.en.png" target="_blank" rel="noreferrer"><img src="https://joinwell52-ai.github.io/joinwell52/assets/approval-identity-20260904/assets/nested-session.en.png" alt="Figure 2: Top-level Session is excluded while nested Session remains in the digest"></a></p><p><em>Figure 2. With the command unchanged, nested Session data can change the request digest. Source: actual request comparisons and an in-memory counterfactual. S1/S2 are explanatory labels, not real session IDs or a proposal to remove all session bindings. Click the image for full resolution.</em></p><p>As a result, the operation fingerprint stays the same while the request digest changes. The consumption service cannot select the original approval by digest, before it reaches subsequent identity checks. Even with the new wake session recorded, that authorization remains available.</p><p>An in-memory counterfactual isolated the cause: remove only the nested Session field from both request snapshots and call the original digest function. The old and new session requests then have equal digests. We did not change the product or execute the transformed requests.</p><p>This is not a recommendation to recursively delete every <code>session_id</code>. Some operations legitimately depend on scratch-directory ownership, the current executor, or session-bound permissions. Those protections cannot simply disappear.</p><p>The necessary distinction is between <strong>fields that define the operation, fields that document this run, and fields that must be revalidated at execution time</strong>.</p><p>The test discrepancy now makes sense. The lower-level unit test constructs a simpler approval request. The real entry point adds a facts snapshot containing the Session. Both tests may be described as “same operation, new session,” but their request shapes are different.</p><h2 id="_5-authorization-identity-needs-mutation-tests-in-both-directions" tabindex="-1">5. Authorization identity needs mutation tests in both directions <a class="header-anchor" href="#_5-authorization-identity-needs-mutation-tests-in-both-directions" aria-label="Permalink to &quot;5. Authorization identity needs mutation tests in both directions&quot;">​</a></h2><p>These two observations should not receive unrelated quick fixes called “include more fields” and “include fewer fields.”</p><p>Hashing everything is not automatically safe: it can mix incidental execution context into operation identity. Coarse classification is insufficient too: it can make different operations share an approval scope.</p><p>For execution paths that require exact approval, we suggest taking three questions into engineering review before choosing a refactoring scope.</p><p><strong>First, a semantic operation change must invalidate the approval match.</strong> For Git, “still a push” is not enough. Relevant distinctions include the target repository or remote, references, update mode, and other conditions that the approval requires to remain fixed. A digest cannot recover information lost before canonicalization.</p><p><strong>Second, permitted execution-context changes must not accidentally change operation identity.</strong> This does not authorize a new Session automatically. After matching the operation, the system must still verify the current caller, authorization state, and applicable scope. An old receipt is not a new execution grant.</p><p><strong>Third, test between the real request producer and consumer.</strong> Do not only handcraft an ideal CapabilityRequest and establish that consumption works. Feed original tool arguments through the actual adapter and inspect what the system approves and later matches.</p><p>A small useful test set includes the original-operation control, changed target, changed mode, permitted context continuation, changed TASK or executor, cancellation, and repeated consumption. The two key mutation directions have opposing expectations: differences that matter must break the match; permitted continuity should preserve identity while retaining current-authority checks.</p><p>This research also examined a separate identity question: could two tasks with identical text but different task IDs substitute for one another as a dependency? Six parent/dependency cases, each repeated twice, behaved as expected under existing FCoP checks. That positive result bounds the proposed work: <strong>the demonstrated gap is in operation authorization identity, not evidence that the entire task identity system needs replacing</strong>.</p><h2 id="_6-what-this-conclusion-does—and-does-not—establish" tabindex="-1">6. What this conclusion does—and does not—establish <a class="header-anchor" href="#_6-what-this-conclusion-does—and-does-not—establish" aria-label="Permalink to &quot;6. What this conclusion does—and does not—establish&quot;">​</a></h2><p>We have no production incident population or failure-rate estimate. These numbers come from controlled experiments on a fixed commit. Existing tests, field comparisons, and approval-entry observations are different sets; adding them does not produce a system reliability percentage.</p><p>We confirmed two local gaps: loss of concrete operation distinctions in the tested shell Git path, and nested Session data breaking the intended continuation match in real requests. We did not demonstrate anonymous exploitation, actual remote damage, equivalent behavior in every tool, or inevitable occurrence during a complete recovery workflow. The Guardian changes are a methodological comparison, not independently rerun upstream experiments.</p><p>The current status is <strong>research complete; engineering review recommended</strong>. This article announces neither a fix, a frozen implementation contract, nor development authorization. The <a href="/joinwell52/en/research/evidence/2026-09-04-approval-operation-identity">evidence package</a> supplies de-identified observations, claim mappings, and a reader/checker. The checker validates recorded evidence; it does not rerun the product or constitute independent QA. Complete raw fixtures and the product-source execution environment remain local research materials and are not distributed with this draft; the package is not a self-contained environment for reproducing product behavior.</p><p>The final question is simple:</p><p><strong>Using an approval only once is not enough. The system must first establish that the operation consuming it is the one that was approved.</strong></p>`,70))])}const y=i(p,[["render",c]]);export{f as __pageData,y as default};
